import {preservesUnresolvedTrades} from './trade-save-guard.mjs';
/* One local writer and revision stream for solo v3 and roster v4 records. */
import {validate} from './engine.mjs';
import {validateRoster,selectedView} from './roster.mjs';
import {sha256Text,randomSessionId} from './crypto-compat.mjs';
const NAME='ashen-covenant-v3',KEY='current',LEASE='writer';
let dbPromise,owner=null;
export function validRoomMarker(room){const id=value=>typeof value==='string'&&value.length>0&&value.length<=128&&value.trim()===value&&!/[\u0000-\u001f\u007f]/.test(value);return !!room&&typeof room==='object'&&!Array.isArray(room)&&Object.keys(room).every(key=>['roomId','memberId','sequence'].includes(key))&&id(room.roomId)&&id(room.memberId)&&Number.isSafeInteger(room.sequence)&&room.sequence>=0}
export async function checksum(text){return sha256Text(text)}
export function openDB(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{if(!globalThis.indexedDB)return reject(Error('本機儲存無法使用'));const r=indexedDB.open(NAME,1);r.onupgradeneeded=()=>{for(const n of ['save','archives','journal','legacy','leases'])if(!r.result.objectStoreNames.contains(n))r.result.createObjectStore(n)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('請關閉另一個舊分頁後再開啟'))});return dbPromise}
async function get(store,key){const d=await openDB();return new Promise((resolve,reject)=>{const r=d.transaction(store,'readonly').objectStore(store).get(key);r.onsuccess=()=>resolve(r.result??null);r.onerror=()=>reject(r.error)})}
async function decodePayload(env){const isRoster=Object.hasOwn(env,'rosterJSON');if(isRoster&&Object.hasOwn(env,'stateJSON'))throw Error('存檔含有互相衝突的帳本');if(isRoster&&env.schema!==4&&env.format!=='ashen-covenant-v4'||isRoster&&env.schema!==undefined&&env.schema!==4)throw Error('帳本版本無效');if(!isRoster&&(env.schema!==undefined&&env.schema!==3))throw Error('存檔版本無效');const raw=isRoster?env.rosterJSON:env.stateJSON;if(typeof raw!=='string'||await checksum(raw)!==env.checksum)throw Error('存檔校驗失敗，已停止覆寫');const payload=JSON.parse(raw),r=isRoster?validateRoster(payload):validate(payload);if(!r.ok)throw Error('存檔不相容：'+r.errors.join('；'));return isRoster?{roster:payload,state:selectedView(payload)}:{state:payload}}
function encodePayload(payload,isRoster){const v=isRoster?validateRoster(payload):validate(payload);if(!v.ok)throw Error('拒絕儲存無效狀態：'+v.errors.join('；'));const raw=JSON.stringify(payload),snapshot=JSON.parse(raw);return{raw,fields:isRoster?{rosterJSON:raw}:{stateJSON:raw},state:isRoster?selectedView(snapshot):snapshot,...(isRoster?{roster:snapshot}:{})}}
export async function decodeEnvelope(env){if(env==null)return null;if(env.room!==undefined&&!validRoomMarker(env.room))throw Error('連線保存標記無效');if(!Number.isSafeInteger(env.revision)||env.revision<1||!Number.isFinite(env.resolvedAt)||env.resolvedAt<0)throw Error('存檔修訂或時間無效，已停止覆寫');return{...env,...await decodePayload(env)}}
export async function readSave(){return decodeEnvelope(await get('save',KEY))}
export async function readRecovery(){return decodeEnvelope(await get('save','last-known-good'))}
export function writeSave(state,expectedRevision,resolvedAt,options={}){return writeRecord(state,false,expectedRevision,resolvedAt,options)}
export function writeRoster(roster,expectedRevision,resolvedAt,options={}){return writeRecord(roster,true,expectedRevision,resolvedAt,options)}
async function writeRecord(payload,isRoster,expectedRevision,resolvedAt,{archive=false,operation='checkpoint',recoveryCurrentJSON,room}={}){if(room!==undefined&&!validRoomMarker(room))throw Error('連線保存標記無效');const roomSnapshot=room===undefined?undefined:{...room};const encoded=encodePayload(payload,isRoster);if(!owner)throw Error('此分頁没有寫入權限');if(!Number.isSafeInteger(expectedRevision)||expectedRevision<0||!Number.isFinite(resolvedAt)||resolvedAt<0)throw Error('存檔修訂或時間無效');const digest=await checksum(encoded.raw),snapshot=encoded.state,d=await openDB();return new Promise((resolve,reject)=>{const tx=d.transaction(['save','archives','journal','leases'],'readwrite'),save=tx.objectStore('save');let old,lease,reads=0,result,failed=false;function abort(message){failed=true;try{tx.abort()}catch{}reject(Error(message))}function commit(){if(++reads<2)return;if(lease?.owner!==owner)return abort('寫入租約已失效，請重新載入');if((old?.revision||0)!==expectedRevision)return abort('另一分頁已更新進度，已阻止覆寫');if(recoveryCurrentJSON!==undefined&&JSON.stringify(old)!==recoveryCurrentJSON)return abort('原始存檔已變更，請重新預覽復原候選');const revision=expectedRevision+1;result={schema:isRoster?4:3,revision,resolvedAt,checksum:digest,...encoded.fields,contentVersion:snapshot.contentVersion,...(roomSnapshot?{room:roomSnapshot}:{})};if(old){if(recoveryCurrentJSON===undefined)save.put(old,'last-known-good');if(archive)tx.objectStore('archives').put(old,'before-'+old.revision)}save.put(result,KEY);tx.objectStore('journal').put({revision,operation,previousChecksum:old?.checksum||null,checksum:digest,resolvedAt,simulationMs:snapshot.elapsedMs},revision%512);tx.objectStore('leases').put({...lease,expiresAt:Date.now()+30000},LEASE)}const r=save.get(KEY);r.onsuccess=()=>{old=r.result;commit()};r.onerror=()=>abort('讀取目前修訂失敗');const l=tx.objectStore('leases').get(LEASE);l.onsuccess=()=>{lease=l.result;commit()};l.onerror=()=>abort('讀取寫入租約失敗');tx.oncomplete=()=>resolve({...result,state:encoded.state,...(isRoster?{roster:encoded.roster}:{})});tx.onerror=()=>{if(!failed)reject(tx.error||Error('儲存失敗，原快照保留'))};tx.onabort=()=>{if(!failed)reject(tx.error||Error('儲存中斷，原快照保留'))}})}
async function lease(action){const d=await openDB(),token=owner;return new Promise((resolve,reject)=>{const tx=d.transaction('leases','readwrite'),store=tx.objectStore('leases'),r=store.get(LEASE);let ok=false;r.onsuccess=()=>{const previous=r.result,now=Date.now();if(action==='release'){if(previous?.owner===token)store.delete(LEASE);ok=true}else if(!previous||previous.expiresAt<now||previous.owner===token){store.put({owner:token,expiresAt:now+30000},LEASE);ok=true}};tx.oncomplete=()=>resolve(ok);tx.onerror=()=>reject(tx.error)})}
export async function acquireSession(){owner=randomSessionId();let releaseLock=null,lockFinished=Promise.resolve();if(navigator.locks?.request){const granted=await new Promise(resolve=>lockFinished=navigator.locks.request('ashen-covenant-play',{ifAvailable:true},async lock=>{if(!lock)return resolve(false);const holding=new Promise(r=>releaseLock=r);resolve(true);await holding}).catch(()=>resolve(false)));if(!granted){owner=null;return{owned:false,release(){}}}}const acquired=await lease('acquire');if(!acquired){releaseLock?.();await lockFinished;owner=null;return{owned:false,release(){}}}const timer=setInterval(()=>lease('renew').then(ok=>{if(!ok){owner=null;clearInterval(timer)}}).catch(()=>{}),10000);return{owned:true,async release(){clearInterval(timer);await lease('release');owner=null;releaseLock?.();await lockFinished}}}
export async function listArchives(){const d=await openDB();return new Promise((resolve,reject)=>{const r=d.transaction('archives','readonly').objectStore('archives').getAll();r.onsuccess=()=>resolve(r.result.sort((a,b)=>b.revision-a.revision));r.onerror=()=>reject(r.error)})}

// Read-only inspection keeps malformed originals available without decoding them.
export async function exportRawSave(){const current=await get('save',KEY);return current!=null?{format:'ashen-covenant-v3-recovery-raw',exportedAt:new Date().toISOString(),envelope:current}:null}
async function recoveryEnvelopes(){const d=await openDB();return new Promise((resolve,reject)=>{const tx=d.transaction(['save','archives'],'readonly'),rows=[];let current=null;const saved=tx.objectStore('save').get(KEY);saved.onsuccess=()=>current=saved.result??null;const last=tx.objectStore('save').get('last-known-good');last.onsuccess=()=>{if(last.result!=null)rows.push({key:'last-known-good',envelope:last.result})};const archives=tx.objectStore('archives').openCursor();archives.onsuccess=()=>{const cursor=archives.result;if(cursor){rows.push({key:'archive:'+cursor.key,envelope:cursor.value});cursor.continue()}};tx.oncomplete=()=>resolve({current,rows});tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('讀取復原候選中斷'))})}
export async function inspectRecovery(){const {current,rows}=await recoveryEnvelopes(),candidates=[];for(const row of rows){const candidate={key:row.key,fingerprint:await checksum(JSON.stringify(row.envelope)),revision:row.envelope?.revision,resolvedAt:row.envelope?.resolvedAt,valid:false};try{const env=await decodeEnvelope(row.envelope);Object.assign(candidate,{valid:true,name:env.state.player.name,level:env.state.player.level,map:env.state.player.map})}catch(error){candidate.error=error.message}candidates.push(candidate)}candidates.sort((a,b)=>(b.revision||0)-(a.revision||0));return{currentAvailable:current!=null,currentFingerprint:current!=null?await checksum(JSON.stringify(current)):null,candidates}}
export async function restoreRecovery(key,currentFingerprint,candidateFingerprint){const {current,rows}=await recoveryEnvelopes();if(!current||await checksum(JSON.stringify(current))!==currentFingerprint)throw Error('原始存檔已變更，請重新預覽復原候選');if(!Number.isSafeInteger(current.revision)||current.revision<1)throw Error('原始修訂損毀，請先匯出原始資料');const selected=rows.find(row=>row.key===key);if(!selected)throw Error('復原候選已不存在');if(await checksum(JSON.stringify(selected.envelope))!==candidateFingerprint)throw Error('復原候選已變更，請重新預覽');const env=await decodeEnvelope(selected.envelope);let latest=null;for(const raw of [current,...rows.map(row=>row.envelope)])try{const decoded=await decodeEnvelope(raw);if(decoded&&(!latest||decoded.revision>latest.revision))latest=decoded}catch{}if(latest&&!preservesUnresolvedTrades(env,latest))throw Error('復原候選會遺失尚未完成的交易；請選保留暫鎖紀錄的候選，並連回原房主處理');return (env.roster?writeRoster:writeSave)(env.roster??env.state,current.revision,env.resolvedAt,{archive:true,operation:'confirmed-recovery',recoveryCurrentJSON:JSON.stringify(current),room:env.room})}
async function readV2(){return new Promise((resolve,reject)=>{let absent=false;const r=indexedDB.open('ashen-covenant-v2');r.onupgradeneeded=()=>{absent=true;r.transaction.abort()};r.onerror=()=>absent?resolve(null):reject(r.error);r.onsuccess=()=>{const d=r.result;if(!d.objectStoreNames.contains('save')){d.close();return resolve(null)}const tx=d.transaction(['save',...(d.objectStoreNames.contains('archives')?['archives']:[])],'readonly'),a=tx.objectStore('save').get('current');let current=null,archives=[];a.onsuccess=()=>current=a.result||null;if(d.objectStoreNames.contains('archives')){const b=tx.objectStore('archives').getAll();b.onsuccess=()=>archives=b.result}tx.oncomplete=()=>{d.close();resolve({current,archives})};tx.onerror=()=>{d.close();reject(tx.error)}}})}
export async function preserveLegacy(){const v1=localStorage.getItem('ashen-covenant-v1'),v2=await readV2(),d=await openDB();const records=[];if(v1)records.push({key:'v1-original',format:'v1-raw',raw:v1});if(v2?.current||v2?.archives.length)records.push({key:'v2-original-'+(v2.current?.revision||0),format:'v2-envelope',raw:JSON.stringify(v2)});await new Promise((resolve,reject)=>{const tx=d.transaction('legacy','readwrite'),store=tx.objectStore('legacy');for(const row of records){const r=store.get(row.key);r.onsuccess=()=>{if(!r.result)store.add({...row,preservedAt:Date.now()},row.key)}}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});return listLegacy()}
export async function listLegacy(){const d=await openDB();return new Promise((resolve,reject)=>{const r=d.transaction('legacy','readonly').objectStore('legacy').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
export function exportEnvelope(state,resolvedAt,options={}){return exportRecord(state,false,resolvedAt,options)}
export function exportRoster(roster,resolvedAt,options={}){return exportRecord(roster,true,resolvedAt,options)}
async function exportRecord(payload,isRoster,resolvedAt,{room}={}){if(room!==undefined&&!validRoomMarker(room))throw Error('連線保存標記無效');if(!Number.isFinite(resolvedAt)||resolvedAt<0)throw Error('備份時間無效');const encoded=encodePayload(payload,isRoster);return{format:isRoster?'ashen-covenant-v4':'ashen-covenant-v3',exportedAt:new Date().toISOString(),resolvedAt,checksum:await checksum(encoded.raw),...encoded.fields,...(room?{room:{...room}}:{})}}
export async function parseImport(raw){const input=JSON.parse(raw);if(!['ashen-covenant-v3','ashen-covenant-v4'].includes(input.format))return{legacy:true,format:input.format||input.version||input.schema,raw};if(input.room!==undefined&&!validRoomMarker(input.room))throw Error('連線保存標記無效');if(!Number.isFinite(input.resolvedAt)||input.resolvedAt<0)throw Error('備份時間無效');if(input.format==='ashen-covenant-v4'&&!Object.hasOwn(input,'rosterJSON')||input.format==='ashen-covenant-v3'&&Object.hasOwn(input,'rosterJSON'))throw Error('備份版本與內容不符');const decoded=await decodePayload(input);return{...decoded,exportedAt:input.exportedAt,resolvedAt:input.resolvedAt,...(input.room?{room:{...input.room}}:{})}}
